CREATE TABLE ordinary_draft(id TEXT PRIMARY KEY,generation TEXT NOT NULL,operation TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('item','dose','correction','profile','dailyPlan','pausePlan','phasePlan','itemType','stockContainer','stockAdjustment','productLabel','combinedDose','combinedCorrection','siteEdit','event','usePeriod','eventReview')),person TEXT REFERENCES person(id),person_revision INTEGER,target TEXT,target_revision INTEGER,snapshot TEXT NOT NULL) STRICT;
CREATE TABLE pause_change(id TEXT PRIMARY KEY,plan TEXT NOT NULL,person TEXT NOT NULL,revision INTEGER NOT NULL,before_snapshot TEXT NOT NULL,after_snapshot TEXT NOT NULL,recorded_at INTEGER NOT NULL,UNIQUE(plan,revision),FOREIGN KEY(plan,person) REFERENCES daily_plan(id,person) ON DELETE CASCADE) STRICT;
CREATE TABLE person(id TEXT PRIMARY KEY, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0), adult_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(adult_confirmed IN (0,1)), report_name TEXT, relationship TEXT, notes TEXT, reminders_stopped INTEGER NOT NULL DEFAULT 0 CHECK(reminders_stopped IN (0,1))) STRICT;
INSERT INTO "person" VALUES ('me','Me',0,1,0,NULL,NULL,NULL,0);
CREATE TABLE personal_item_type(id TEXT PRIMARY KEY,person TEXT NOT NULL REFERENCES person(id),name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),UNIQUE(person,name),UNIQUE(id,person)) STRICT;
INSERT INTO "personal_item_type" VALUES ('a7ca4bd07fe669bc95b9e6eb9989f3e3f3841014b8ec7210','me','medicine',1);
CREATE TABLE phase_change(id TEXT PRIMARY KEY,plan TEXT NOT NULL,person TEXT NOT NULL,revision INTEGER NOT NULL,snapshot TEXT NOT NULL,recorded_at INTEGER NOT NULL,UNIQUE(plan,revision),FOREIGN KEY(plan,person) REFERENCES daily_plan(id,person) ON DELETE CASCADE) STRICT;
CREATE TABLE phase_override(plan TEXT NOT NULL,person TEXT NOT NULL,identity TEXT NOT NULL,origin_date TEXT NOT NULL,target_date TEXT NOT NULL,snapshot TEXT NOT NULL,PRIMARY KEY(plan,identity),FOREIGN KEY(plan,person) REFERENCES daily_plan(id,person) ON DELETE CASCADE) STRICT;
CREATE TABLE phase_plan(plan TEXT PRIMARY KEY,person TEXT NOT NULL,snapshot TEXT NOT NULL,FOREIGN KEY(plan,person) REFERENCES daily_plan(id,person) ON DELETE CASCADE) STRICT;
CREATE TABLE product_label(item TEXT NOT NULL,person TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),snapshot TEXT NOT NULL CHECK(length(snapshot)<=32000 AND json_valid(snapshot) AND json_extract(snapshot,'$.personId') IS person AND json_extract(snapshot,'$.itemId') IS item AND json_extract(snapshot,'$.revision') IS revision AND json_array_length(snapshot,'$.components') BETWEEN 2 AND 32),PRIMARY KEY(item,revision),FOREIGN KEY(item,person) REFERENCES item(id,person) ON DELETE CASCADE) STRICT;
CREATE TABLE reminder_config(plan TEXT PRIMARY KEY,person TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),revision INTEGER NOT NULL CHECK(revision>0),FOREIGN KEY(plan,person) REFERENCES daily_plan(id,person) ON DELETE CASCADE) STRICT;
CREATE TABLE reminder_meta(id INTEGER PRIMARY KEY CHECK(id=1),namespace TEXT NOT NULL,sequence INTEGER NOT NULL DEFAULT 0,fingerprint TEXT NOT NULL DEFAULT '') STRICT;
